/* Stand-in for the map page's hammer.min.js (Hammer.js 1.x).
 *
 * The map calls Hammer(canvas, opts).on('drag'|'transform'|..., on_touch_event)
 * and the handler reads e.gesture.center.pageX/.pageY and e.gesture.scale. Only
 * mouse dragging and ctrl+wheel are reproduced, which is enough for the map to
 * pan and pinch the way it does on a touch screen.
 */
(function (global) {
    function Hammer(el, opts) {
        // Hammer 1.x is usable with or without new; the map uses it bare.
        if (!(this instanceof Hammer)) {
            return new Hammer(el, opts);
        }

        this.el = el;
        this.opts = opts || {};
        this.handlers = {};

        var self = this;
        var dragging = false;
        var last = null;

        function emit(type, gesture) {
            (self.handlers[type] || []).forEach(function (fn) {
                fn({type: type, gesture: gesture, target: el, preventDefault: function () {}});
            });
        }

        function center(e) {
            return {pageX: e.pageX, pageY: e.pageY};
        }

        el.addEventListener('mousedown', function (e) {
            if (e.button !== 0) {
                return;
            }
            dragging = true;
            last = center(e);
            e.preventDefault();
        });

        global.addEventListener('mouseup', function () {
            dragging = false;
        });

        el.addEventListener('mousemove', function (e) {
            if (!dragging) {
                return;
            }
            if (e.pageX === last.pageX && e.pageY === last.pageY) {
                return;
            }
            emit('dragstart', {center: center(e), scale: 1});
            emit('drag', {center: center(e), scale: 1});
            last = center(e);
        });

        el.addEventListener('wheel', function (e) {
            if (!e.ctrlKey) {
                return;
            }
            emit('transform', {center: center(e), scale: e.deltaY < 0 ? 1.05 : 0.95});
            e.preventDefault();
        }, {passive: false});
    }

    Hammer.prototype.on = function (type, fn) {
        (this.handlers[type] = this.handlers[type] || []).push(fn);
        return this;
    };

    Hammer.plugins = {
        showTouches: function () {},
        fakeMultitouch: function () {},
    };

    global.Hammer = Hammer;
})(window);